INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c1c2c3d4-3303-4000-8000-000000000003', 'b1b2c3d4-3333-4000-8000-000000000003', 3, 'Sinais do Chamado', 'Como Deus fala conosco', '{"text": "Santo In\u00e1cio de Loyola, mestre do discernimento, ensina que Deus nos fala de diversas maneiras:\n\n**1. Consola\u00e7\u00e3o Espiritual**\nUm sentimento profundo de paz, alegria e atra\u00e7\u00e3o por determinado caminho. N\u00e3o \u00e9 euforia passageira, mas uma serenidade duradoura.\n\n**2. Desola\u00e7\u00e3o Espiritual**\nInquieta\u00e7\u00e3o, tristeza, confus\u00e3o \u2014 sinais de que algo n\u00e3o est\u00e1 alinhado com a vontade de Deus.\n\n**3. Mo\u00e7\u00f5es Interiores**\nDesejos persistentes que surgem na ora\u00e7\u00e3o e se confirmam com o tempo.\n\n**4. Sinais Exteriores**\nCircunst\u00e2ncias providenciais, conselhos de diretores espirituais, portas que se abrem ou fecham.\n\n\"Em tempo de desola\u00e7\u00e3o, nunca fazer mudan\u00e7a.\" \u2014 Santo In\u00e1cio\n\nO discernimento requer paci\u00eancia. Deus n\u00e3o tem pressa.", "scripture": "1Rs 19,11-13 \u2014 O Senhor n\u00e3o estava no vento, nem no terremoto, nem no fogo... mas na brisa suave."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;